    public DataPipeline testCreate() throws Throwable {
    DataPipeline entity = null;

    LOGGER.info( "DataPipelineTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a DataPipeline");

    StringBuilder msg = new StringBuilder( "-- Failed to create a DataPipeline" );

    try {
        entity = service.createDataPipeline( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getDataPipelineId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a DataPipeline with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

