    /**
     * Tests getting all DataPipelines.
     *
     * @return    Collection
     */
    public List<DataPipeline> testGetAll() throws Throwable {
    LOGGER.info( "DataPipelineTest:testGetAll() - Retrieving Collection of DataPipelines:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DataPipeline : " );
    List<DataPipeline> collection  = null;

    try {
        // call the static get method on the DataPipelineService
        collection = service.getAllDataPipeline();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DataPipeline currEntity  = null;
            Iterator<DataPipeline> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDataPipelineId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

